    weight: usize,
    tail_idx: Option<usize>,
    count: i32,
}

pub fn zopfli_length_limited_code_lengths(
    frequencies: &[usize],
    n: i32,
    maxbits: i32,
    bitlengths: &mut [u32],
) -> i32 {
    let n = n as usize;

    for i in 0..n {
        bitlengths[i] = 0;
    }

    let mut leaves = Vec::new();
    for i in 0..n {
        if frequencies[i] != 0 {
            leaves.push((frequencies[i], i as i32));
        }
    }

    let numsymbols = leaves.len();

    if (1usize << maxbits as usize) < numsymbols {
        return 1;
    }
    if numsymbols == 0 {
        return 0;
    }
    if numsymbols == 1 {
        bitlengths[leaves[0].1 as usize] = 1;
        return 0;
    }
    if numsymbols == 2 {
        bitlengths[leaves[0].1 as usize] += 1;
        bitlengths[leaves[1].1 as usize] += 1;
        return 0;
    }

    let mut leaves_enc = Vec::new();
    for (weight, symbol_idx) in leaves.iter() {
        if *weight >= (1usize << (std::mem::size_of::<usize>() * 8 - 9)) {
            return 1;
        }
        leaves_enc.push(((weight << 9) | (*symbol_idx as usize), *symbol_idx));
    }

    leaves_enc.sort_by_key(|&(w, _)| w);

    let leaves: Vec<(usize, i32)> = leaves_enc
        .iter()
        .map(|&(w, idx)| (w >> 9, idx))
        .collect();

    let mut maxbits = maxbits as i32;
    if numsymbols as i32 - 1 < maxbits {
        maxbits = numsymbols as i32 - 1;
    }
    let maxbits = maxbits as usize;

    let mut nodes = vec![
        Node {
            weight: 0,
            tail_idx: None,
            count: 0
        };
        maxbits * 2 * numsymbols
    ];
    let mut next_idx = 0usize;

    let node0_idx = next_idx;
    next_idx += 1;
    nodes[node0_idx] = Node {
        weight: leaves[0].0,
        tail_idx: None,
        count: 1,
    };

    let node1_idx = next_idx;
    next_idx += 1;
    nodes[node1_idx] = Node {
        weight: leaves[1].0,
        tail_idx: None,
        count: 2,
    };

    let mut lists = vec![(node0_idx, node1_idx); maxbits];

    let num_boundary_pm_runs = 2 * numsymbols - 4;
    for _ in 0..(num_boundary_pm_runs - 1) {
        boundary_pm(
            &mut nodes,
            &mut lists,
            &leaves,
            numsymbols,
            &mut next_idx,
            maxbits - 1,
        );
    }
    boundary_pm_final(&mut nodes, &mut lists, &leaves, numsymbols, next_idx, maxbits - 1);

    extract_bit_lengths(&nodes, lists[maxbits - 1].1, &leaves, bitlengths);

    0
}

fn boundary_pm(
    nodes: &mut [Node],
    lists: &mut [(usize, usize)],
    leaves: &[(usize, i32)],
    numsymbols: usize,
    next_idx: &mut usize,
    index: usize,
) {
    let lastcount = nodes[lists[index].1].count;

    if index == 0 && lastcount >= numsymbols as i32 {
        return;
    }

    let newchain_idx = *next_idx;
    *next_idx += 1;
    let oldchain_idx = lists[index].1;

    lists[index].0 = oldchain_idx;
    lists[index].1 = newchain_idx;

    if index == 0 {
        nodes[newchain_idx] = Node {
            weight: leaves[lastcount as usize].0,
            tail_idx: None,
            count: lastcount + 1,
        };
    } else {
        let sum = nodes[lists[index - 1].0].weight + nodes[lists[index - 1].1].weight;
        if (lastcount as usize) < numsymbols && sum > leaves[lastcount as usize].0 {
            nodes[newchain_idx] = Node {
                weight: leaves[lastcount as usize].0,
                tail_idx: nodes[oldchain_idx].tail_idx,
                count: lastcount + 1,
            };
        } else {
            nodes[newchain_idx] = Node {
                weight: sum,
                tail_idx: Some(lists[index - 1].1),
                count: lastcount,
            };
            boundary_pm(nodes, lists, leaves, numsymbols, next_idx, index - 1);
            boundary_pm(nodes, lists, leaves, numsymbols, next_idx, index - 1);
        }
    }
}

fn boundary_pm_final(
    nodes: &mut [Node],
    lists: &mut [(usize, usize)],
    leaves: &[(usize, i32)],
    numsymbols: usize,
    next_idx: usize,
    index: usize,
) {
    let lastcount = nodes[lists[index].1].count;
    let sum = nodes[lists[index - 1].0].weight + nodes[lists[index - 1].1].weight;

    if (lastcount as usize) < numsymbols && sum > leaves[lastcount as usize].0 {
        let oldchain_idx = nodes[lists[index].1].tail_idx;
        let newchain_idx = next_idx;
        lists[index].1 = newchain_idx;
        nodes[newchain_idx].count = lastcount + 1;
        nodes[newchain_idx].tail_idx = oldchain_idx;
    } else {
        nodes[lists[index].1].tail_idx = Some(lists[index - 1].1);
    }
}

fn extract_bit_lengths(
    nodes: &[Node],
    chain_idx: usize,
    leaves: &[(usize, i32)],
    bitlengths: &mut [u32],
) {
    let mut counts = [0i32; 16];
    let mut end = 16usize;
    let mut ptr = 15usize;
    let mut value = 1u32;

    let mut current = Some(chain_idx);
    while let Some(idx) = current {
        end = end.saturating_sub(1);
        counts[end] = nodes[idx].count;
        current = nodes[idx].tail_idx;
    }

    let mut val = counts[15];
    while ptr >= end {
        while val > counts[ptr - 1] {
            let leaf_idx = (val - 1) as usize;
            bitlengths[leaves[leaf_idx].1 as usize] = value;
            val -= 1;
        }
        ptr = ptr.saturating_sub(1);
        value += 1;
    }
}
